import{_ as t,o as i,c as a,a0 as r}from"./chunks/framework.DB31oXgM.js";const f=JSON.parse('{"title":"01 - Vision & Scope: Rollback Netcode Server","description":"","frontmatter":{},"headers":[],"relativePath":"01-vision-and-scope.md","filePath":"01-vision-and-scope.md"}'),n={name:"01-vision-and-scope.md"};function s(o,e,l,d,c,m){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_01-vision-scope-rollback-netcode-server" tabindex="-1">01 - Vision &amp; Scope: Rollback Netcode Server <a class="header-anchor" href="#_01-vision-scope-rollback-netcode-server" aria-label="Permalink to &quot;01 - Vision &amp; Scope: Rollback Netcode Server&quot;">​</a></h1><h2 id="_1-executive-summary-specified" tabindex="-1">1. Executive Summary [Specified] <a class="header-anchor" href="#_1-executive-summary-specified" aria-label="Permalink to &quot;1. Executive Summary [Specified]&quot;">​</a></h2><p>In multiplayer real-time network gaming, latency is the defining constraint of player experience. Traditional lockstep architectures introduce severe input lag equal to the Round-Trip Time (RTT) of the slowest peer, while basic server-authoritative client-side prediction systems suffer from jarring teleportation artifacts and non-deterministic state divergence when remote inputs arrive late.</p><p><code>rollback-netcode-server</code> provides a state-of-the-art, deterministic, server-authoritative multiplayer netcode engine and client runtime designed for competitive 2D arena combat. The engine combines deterministic fixed-point physics (Q16.16), a snapshot circular ring buffer (128 frames), rollback resimulation (rewinding up to 128 frames in sub-millisecond time), packet redundancy over UDP, continuous Blake3 frame state checksumming for sub-frame desync detection, and an integrated Machine Learning subsystem featuring real-time input anomaly detection (cheat detection), adaptive jitter prediction, and an LLM-powered desync diagnostic assistant.</p><h2 id="_2-core-value-proposition-problem-statement-specified" tabindex="-1">2. Core Value Proposition &amp; Problem Statement [Specified] <a class="header-anchor" href="#_2-core-value-proposition-problem-statement-specified" aria-label="Permalink to &quot;2. Core Value Proposition &amp; Problem Statement [Specified]&quot;">​</a></h2><ul><li><strong>Zero Perceived Input Lag</strong>: Local player inputs are executed immediately on the local frame without waiting for server or remote player confirmation.</li><li><strong>Strict Server Authority</strong>: Unlike peer-to-peer rollback engines (e.g. GGPO) where malicious peers can forge state, our architecture is server-authoritative. The server maintains the true master simulation, validates input feasibility, executes rollback resimulation upon receiving late client inputs, and acts as the final arbiter.</li><li><strong>Guaranteed Determinism</strong>: All arithmetic uses fixed-point math (<code>FixedI32</code>), avoiding IEEE 754 floating-point non-determinism across disparate CPU architectures (x86_64, ARM64, WASM).</li><li><strong>Sub-Frame Desync Diagnostics</strong>: Every frame produces a 64-bit Blake3 checksum over canonical state memory. Any client-server divergence triggers an immediate binary differential dump and automated root-cause analysis.</li><li><strong>Built-in AI Operations</strong>: Autonomous cheat detection on raw input sequences and predictive jitter modeling to dynamically calibrate the local input delay window.</li></ul><h2 id="_3-system-boundaries-target-performance-specified" tabindex="-1">3. System Boundaries &amp; Target Performance [Specified] <a class="header-anchor" href="#_3-system-boundaries-target-performance-specified" aria-label="Permalink to &quot;3. System Boundaries &amp; Target Performance [Specified]&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Metric</th><th style="text-align:left;">Specification Target</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;">Simulation Tick Rate</td><td style="text-align:left;">60.0 Hz (16.666 ms fixed interval)</td><td style="text-align:left;">[Specified]</td></tr><tr><td style="text-align:left;">Max Supported Rollback Window</td><td style="text-align:left;">128 frames (2.13 seconds)</td><td style="text-align:left;">[Specified]</td></tr><tr><td style="text-align:left;">Rollback Resimulation Overhead (8 frames)</td><td style="text-align:left;">&lt; 0.25 ms on modern x86_64 / ARM64</td><td style="text-align:left;"><strong>TO BE MEASURED</strong></td></tr><tr><td style="text-align:left;">Rollback Resimulation Overhead (64 frames)</td><td style="text-align:left;">&lt; 1.80 ms on modern x86_64 / ARM64</td><td style="text-align:left;"><strong>TO BE MEASURED</strong></td></tr><tr><td style="text-align:left;">State Snapshot Size</td><td style="text-align:left;">&lt;= 512 bytes per frame (uncompressed)</td><td style="text-align:left;">[Specified]</td></tr><tr><td style="text-align:left;">Determinism Verification</td><td style="text-align:left;">1,000,000 continuous frames zero divergence</td><td style="text-align:left;">[Specified]</td></tr><tr><td style="text-align:left;">Telemetry Ingestion Throughput</td><td style="text-align:left;">&gt;= 25,000 events/sec</td><td style="text-align:left;"><strong>TO BE MEASURED</strong></td></tr><tr><td style="text-align:left;">Cheat Detection Inference Latency</td><td style="text-align:left;">&lt; 5.0 ms per 60-frame window</td><td style="text-align:left;"><strong>TO BE MEASURED</strong></td></tr><tr><td style="text-align:left;">Jitter Predictor Inference Latency</td><td style="text-align:left;">&lt; 0.1 ms per packet step</td><td style="text-align:left;"><strong>TO BE MEASURED</strong></td></tr></tbody></table><h2 id="_4-user-personas-specified" tabindex="-1">4. User Personas [Specified] <a class="header-anchor" href="#_4-user-personas-specified" aria-label="Permalink to &quot;4. User Personas [Specified]&quot;">​</a></h2><ol><li><strong>Competitive Esports Players</strong>: Require responsive &lt; 1 frame perceived input latency and zero teleportation artifacts under typical network jitter (&lt; 60 ms).</li><li><strong>Game Systems Engineers</strong>: Need full visibility into snapshot ring buffers, rollback frequencies, clock drift, and deterministic frame logs.</li><li><strong>Game Anti-Cheat Operations</strong>: Require telemetry on input rates, impossibility metrics, and automated anomaly scoring.</li></ol>',10)])])}const u=t(n,[["render",s]]);export{f as __pageData,u as default};
